const cfg = $('Configure Clinic Settings').first().json;
const windowMs = Number(cfg.reminderWindowHours || 24) * 3600 * 1000;
const now = Date.now();
const results = [];

for (const item of $input.all()) {
  const row = item.json;
  const cleanPhone = String(row.phone || '').replace(/\D/g, '');
  const apptMs = Date.parse(String(row.appointmentIso || ''));
  const status = String(row.status || 'Scheduled').trim().toLowerCase();
  const sent = String(row.reminderSent || '').trim().toLowerCase() === 'yes';
  if (cleanPhone.length >= 8 && !Number.isNaN(apptMs) && status === 'scheduled' && !sent) {
    const delta = apptMs - now;
    if (delta > 15 * 60 * 1000 && delta <= windowMs) {
      const formattedTime = new Date(apptMs).toUTCString().replace(':00 GMT', ' UTC');
      results.push({
        json: {
          bookingId: String(row.bookingId || `${cleanPhone}-${apptMs}`),
          cleanPhone,
          clientName: String(row.clientName || 'there').trim(),
          serviceName: String(row.serviceName || 'appointment').trim(),
          appointmentIso: String(row.appointmentIso),
          formattedTime,
          calendarEventId: String(row.calendarEventId || '').trim(),
          businessName: cfg.businessName,
          spreadsheetId: cfg.spreadsheetId,
          calendarId: cfg.calendarId,
        },
      });
    }
  }
}
return results;

const voteEvent = $('When Client Votes on WhatsApp Poll').first().json;
const cfg = $('Configure Callback Settings').first().json;
const indices = voteEvent.vote?.selectedOptionIndices || [];
if (!Array.isArray(indices) || indices.length === 0) return [];

const choiceIndex = Number(indices[0]);
const chatId = String(voteEvent.chat?.id || '');
const voterDigits = chatId.replace(/@.*$/, '').replace(/\D/g, '');
if (!voterDigits) return [];

const now = Date.now();
const matching = $input.all()
  .map((i) => i.json)
  .filter((r) => {
    const rowPhone = String(r.phone || '').replace(/\D/g, '');
    const apptMs = Date.parse(String(r.appointmentIso || ''));
    return rowPhone === voterDigits && !Number.isNaN(apptMs) && apptMs > now - 2 * 3600 * 1000;
  })
  .sort((a, b) => Date.parse(String(a.appointmentIso)) - Date.parse(String(b.appointmentIso)));

const booking = matching[0];
if (!booking) return [];

const statusMap = { 0: 'Confirmed', 1: 'Running Late', 2: 'Reschedule Requested' };
const newStatus = statusMap[choiceIndex] || 'Confirmed';
const needsStaffAlert = choiceIndex === 1 || choiceIndex === 2;
const hasStaffGroup = cfg.staffGroupChatId && cfg.staffGroupChatId !== 'YOUR_STAFF_GROUP_ID@g.us';

const replyText = choiceIndex === 2
  ? `No problem, ${booking.clientName || 'there'}! Pick a new time here: ${cfg.rescheduleUrl}`
  : choiceIndex === 1
  ? `Thanks for the heads-up, ${booking.clientName || 'there'}! We let the front desk know you are running ~10 minutes late.`
  : `Thanks for confirming, ${booking.clientName || 'there'}! We look forward to seeing you for your ${booking.serviceName || 'appointment'}.`;

return [{
  json: {
    bookingId: booking.bookingId,
    clientName: booking.clientName || voterDigits,
    serviceName: booking.serviceName || 'Appointment',
    appointmentIso: booking.appointmentIso,
    chatId,
    newStatus,
    replyText,
    shouldAlertStaff: Boolean(needsStaffAlert && hasStaffGroup),
    staffGroupChatId: cfg.staffGroupChatId,
    spreadsheetId: cfg.spreadsheetId,
  },
}];
